-- Initial read-only import of Baljuora catalog snapshot (2026-09-15).
-- Source: authenticated product list with visibility/sold-out filters set to 전체; no external writes performed.
CREATE TABLE IF NOT EXISTS external_product_links (
  id TEXT PRIMARY KEY, provider TEXT NOT NULL, externalProductId TEXT NOT NULL, externalProductCode TEXT NOT NULL, productId TEXT NOT NULL REFERENCES products(id) ON DELETE CASCADE, externalUpdatedAt TEXT, lastPulledAt TEXT NOT NULL, lastPushedAt TEXT, syncStatus TEXT NOT NULL DEFAULT 'imported', sourceHash TEXT, rawSnapshot TEXT, createdAt TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, updatedAt TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE(provider, externalProductId), UNIQUE(provider, externalProductCode)
);
CREATE INDEX IF NOT EXISTS idx_external_product_links_product ON external_product_links(productId);
CREATE INDEX IF NOT EXISTS idx_external_product_links_status ON external_product_links(syncStatus);
CREATE TABLE IF NOT EXISTS product_sync_outbox (
  id TEXT PRIMARY KEY, provider TEXT NOT NULL, productId TEXT NOT NULL REFERENCES products(id) ON DELETE CASCADE, action TEXT NOT NULL, payload TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'blocked', attempts INTEGER NOT NULL DEFAULT 0, lastError TEXT, createdAt TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, processedAt TEXT
);
CREATE INDEX IF NOT EXISTS idx_product_sync_outbox_status ON product_sync_outbox(status, createdAt);
CREATE TABLE IF NOT EXISTS sync_runs (
  id TEXT PRIMARY KEY, provider TEXT NOT NULL, direction TEXT NOT NULL, trigger TEXT NOT NULL, total INTEGER NOT NULL DEFAULT 0, createdCount INTEGER NOT NULL DEFAULT 0, updatedCount INTEGER NOT NULL DEFAULT 0, skippedCount INTEGER NOT NULL DEFAULT 0, failedCount INTEGER NOT NULL DEFAULT 0, conflictCount INTEGER NOT NULL DEFAULT 0, status TEXT NOT NULL DEFAULT 'completed', checkpoint TEXT, errorMessage TEXT, startedAt TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, finishedAt TEXT
);
CREATE INDEX IF NOT EXISTS idx_sync_runs_provider_started ON sync_runs(provider, startedAt);

